/* 落位 Floorcraft · 空间布局工作台 */
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg: #12151c;
  --panel: #1a1f2a;
  --panel2: #151a24;
  --line: #2a3140;
  --text: #e8ecf4;
  --dim: #93a0b4;
  --faint: #6b7688;
  --accent: #5b8def;
  --ok: #2fae7d;
  --warn: #d0912f;
  --bad: #e05b5b;
  --radius: 10px;
  font-size: 14px;
}

html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;
  overflow: hidden;
}

#app { display: flex; flex-direction: column; height: 100vh; outline: none; }

kbd {
  font: 11px/1.4 Consolas, monospace;
  background: #262d3a;
  border: 1px solid #3a4356;
  border-bottom-width: 2px;
  border-radius: 4px;
  padding: 1px 5px;
  color: #c6d0e0;
  margin: 0 1px;
  white-space: nowrap;
}

/* ── 顶栏 ─────────────────────────────── */
#topbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px; padding: 10px 16px;
  background: var(--panel); border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 10px; }
.logo {
  width: 34px; height: 34px; display: grid; place-items: center;
  font-size: 17px; color: #fff;
  background: linear-gradient(135deg, #5b8def, #7a5bef);
  border-radius: 9px;
}
.brand h1 { font-size: 16px; font-weight: 650; letter-spacing: .5px; }
.brand h1 i { font-style: italic; font-weight: 400; color: var(--dim); font-size: 13px; }
.brand p { font-size: 11px; color: var(--dim); margin-top: 1px; }

.tools { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }

button {
  font: inherit; color: var(--text); cursor: pointer;
  background: #232a38; border: 1px solid var(--line);
  border-radius: 8px; padding: 6px 11px;
  transition: background .12s, border-color .12s;
}
button:hover { background: #2b3446; border-color: #3d4759; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
button.primary:hover { background: #6c9af2; }
button.toggle { color: var(--dim); }
button.toggle.on { color: #bfe3c9; border-color: #2fae7d66; background: #1d2b26; }
button kbd { margin-left: 4px; }

.seg { display: flex; background: #1d2330; border: 1px solid var(--line); border-radius: 8px; padding: 2px; gap: 2px; }
.seg button { border: none; background: transparent; padding: 4px 9px; border-radius: 6px; color: var(--dim); font-size: 13px; }
.seg button.on { background: #2f3950; color: var(--text); }

/* ── 主区 ─────────────────────────────── */
#main { flex: 1; display: flex; min-height: 0; }
#stageWrap { flex: 1; position: relative; min-width: 0; }
#stage { width: 100%; height: 100%; display: block; cursor: default; touch-action: none; }
#stage.panning { cursor: grabbing; }

#worldBg { fill: #171c26; stroke: #2a3140; stroke-width: 1.5; }

.zone-rect { rx: 16; }
.zone-name { font: 600 13px "Segoe UI", "Microsoft YaHei", sans-serif; fill: var(--dim); letter-spacing: 1px; }
.zone-sub  { font: 11px "Segoe UI", "Microsoft YaHei", sans-serif; fill: var(--faint); }

.obj { cursor: move; }
.obj text {
  font: 11px "Segoe UI", "Microsoft YaHei", sans-serif;
  text-anchor: middle; pointer-events: none; user-select: none;
}
.obj .body { fill: #232b3a; stroke-width: 2; }
.obj.unplaced .body { stroke-dasharray: 4 3; }
.obj.unplaced text { fill: var(--faint); }
.selring {
  fill: none; stroke: #fff; stroke-width: 1.6; stroke-dasharray: 5 4;
  animation: march 0.8s linear infinite; pointer-events: none;
}
@keyframes march { to { stroke-dashoffset: -9; } }
.obj.dim { opacity: .55; }

#marquee { fill: #5b8def22; stroke: #5b8def; stroke-width: 1.5; stroke-dasharray: 4 3; }

#zoomCtl { position: absolute; right: 14px; bottom: 14px; display: flex; flex-direction: column; gap: 6px; }
#zoomCtl button { width: 34px; height: 34px; font-size: 15px; padding: 0; background: #1e2530ee; }

#toasts {
  position: absolute; left: 50%; bottom: 18px; transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none;
}
.toast {
  background: #0f1420ee; border: 1px solid #3a4356; color: var(--text);
  padding: 6px 14px; border-radius: 20px; font-size: 12.5px;
  opacity: 0; transform: translateY(6px); transition: all .25s;
}
.toast.in { opacity: 1; transform: none; }
.toast b { color: #9ec1ff; font-weight: 600; }

/* ── 侧栏 ─────────────────────────────── */
#side { width: 292px; background: var(--panel); border-left: 1px solid var(--line); overflow-y: auto; }
.panel { padding: 14px 14px 20px; }
.panel h2 { font-size: 13.5px; font-weight: 650; letter-spacing: .5px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.panel .tag { font-size: 10.5px; font-weight: 400; color: var(--accent); background: #5b8def1c; border: 1px solid #5b8def44; padding: 1px 7px; border-radius: 10px; }
.panel .note { font-size: 11.5px; color: var(--faint); line-height: 1.55; margin: 8px 0 12px; }

.zgroup { margin-bottom: 14px; }
.zhead { display: flex; align-items: center; gap: 7px; margin-bottom: 6px; }
.zdot { width: 9px; height: 9px; border-radius: 3px; flex: none; }
.zname { font-size: 12.5px; font-weight: 600; }
.zcount { font-size: 11px; color: var(--faint); margin-left: auto; font-variant-numeric: tabular-nums; }
.zgroup.empty .zname, .zgroup.empty .zcount { color: var(--faint); }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  font: 11.5px "Segoe UI", "Microsoft YaHei", sans-serif;
  color: var(--text); background: #222939; border: 1px solid var(--line);
  border-left: 3px solid var(--acc, #7d8798);
  border-radius: 6px; padding: 3px 8px; cursor: pointer;
}
.chip:hover { background: #2b3446; }
.zgroup.empty .chips::after { content: "—"; color: var(--faint); font-size: 11px; }

/* ── 状态栏 ───────────────────────────── */
#statusbar {
  display: flex; align-items: center; gap: 14px;
  padding: 5px 14px; font-size: 11.5px; color: var(--dim);
  background: var(--panel2); border-top: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
}
#statusbar .grow { flex: 1; }
#statusbar #stSel { color: var(--text); }
#statusbar .hint { color: var(--faint); }
#statusbar .hint kbd { font-size: 10px; padding: 0 3px; }

/* ── 帮助浮层 ─────────────────────────── */
#helpOverlay {
  position: fixed; inset: 0; z-index: 50;
  background: #0a0d13cc; display: grid; place-items: center;
}
#helpOverlay[hidden] { display: none; }
.sheet {
  width: min(560px, 92vw); max-height: 86vh; overflow-y: auto;
  background: var(--panel); border: 1px solid #3a4356; border-radius: 14px;
  padding: 18px 22px; box-shadow: 0 18px 60px #000a;
}
.sheet header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.sheet h2 { font-size: 15px; }
.sheet table { width: 100%; border-collapse: collapse; }
.sheet th {
  text-align: left; font-weight: 500; color: var(--dim); font-size: 12.5px;
  padding: 6px 10px 6px 0; border-bottom: 1px solid var(--line); white-space: nowrap; vertical-align: top;
}
.sheet td { padding: 6px 0; border-bottom: 1px solid var(--line); font-size: 12.5px; }
.sheet .note { margin-top: 12px; font-size: 11.5px; color: var(--faint); line-height: 1.6; }

/* ── 自检面板 ─────────────────────────── */
#selftest {
  position: fixed; right: 12px; top: 64px; z-index: 60;
  width: 340px; max-height: 78vh; overflow-y: auto;
  background: #0f1420f2; border: 1px solid #3a4356; border-radius: 12px;
  padding: 12px 14px; font-size: 12px;
}
#selftest h3 { font-size: 13px; margin-bottom: 8px; }
#selftest h3 .sum-pass { color: var(--ok); }
#selftest h3 .sum-fail { color: var(--bad); }
#selftest ol { list-style: none; }
#selftest li { padding: 3px 0; border-bottom: 1px dashed #232b3a; line-height: 1.45; }
#selftest li b { font-weight: 600; }
#selftest li.pass b { color: var(--ok); }
#selftest li.fail b { color: var(--bad); }
#selftest li span { color: var(--dim); }
#selftest .foot { margin-top: 8px; color: var(--faint); font-size: 11px; line-height: 1.5; }

