.seg { display: flex; background: #1d2330; border: 1px solid var(--line); border-radius: 8px; padding: 2px; gap: 2px; }
.seg button { border: none; background: transparent; padding: 4px 9px; border-radius: 6px; color: var(--dim); font-size: 13px; }
.seg button.on { background: #2f3950; color: var(--text); }

/* ── 主区 ─────────────────────────────── */
#main { flex: 1; display: flex; min-height: 0; }
#stageWrap { flex: 1; position: relative; min-width: 0; }
#stage { width: 100%; height: 100%; display: block; cursor: default; touch-action: none; }
#stage.panning { cursor: grabbing; }

#worldBg { fill: #171c26; stroke: #2a3140; stroke-width: 1.5; }

.zone-rect { rx: 16; }
.zone-name { font: 600 13px "Segoe UI", "Microsoft YaHei", sans-serif; fill: var(--dim); letter-spacing: 1px; }
.zone-sub  { font: 11px "Segoe UI", "Microsoft YaHei", sans-serif; fill: var(--faint); }

.obj { cursor: move; }
.obj text {
  font: 11px "Segoe UI", "Microsoft YaHei", sans-serif;
  text-anchor: middle; pointer-events: none; user-select: none;
}
.obj .body { fill: #232b3a; stroke-width: 2; }
.obj.unplaced .body { stroke-dasharray: 4 3; }
.obj.unplaced text { fill: var(--faint); }
.selring {
  fill: none; stroke: #fff; stroke-width: 1.6; stroke-dasharray: 5 4;
  animation: march 0.8s linear infinite; pointer-events: none;
}
@keyframes march { to { stroke-dashoffset: -9; } }
.obj.dim { opacity: .55; }

#marquee { fill: #5b8def22; stroke: #5b8def; stroke-width: 1.5; stroke-dasharray: 4 3; }

#zoomCtl { position: absolute; right: 14px; bottom: 14px; display: flex; flex-direction: column; gap: 6px; }
