.zgroup.empty .zname, .zgroup.empty .zcount { color: var(--faint); }
.chips { display: flex; flex-wrap: wrap; gap: 5px; }
.chip {
  font: 11.5px "Segoe UI", "Microsoft YaHei", sans-serif;
  color: var(--text); background: #222939; border: 1px solid var(--line);
  border-left: 3px solid var(--acc, #7d8798);
  border-radius: 6px; padding: 3px 8px; cursor: pointer;
}
.chip:hover { background: #2b3446; }
.zgroup.empty .chips::after { content: "—"; color: var(--faint); font-size: 11px; }

/* ── 状态栏 ───────────────────────────── */
#statusbar {
  display: flex; align-items: center; gap: 14px;
  padding: 5px 14px; font-size: 11.5px; color: var(--dim);
