1	'use strict';
2	/* 落位 Floorcraft —— 空间布局工作台
3	 * 核心模型：对象的物理位置（中心点所在分区）即其归属，摆放即数据。
4	 * 所有空间操作在 keys.js 中提供键盘等价物。 */
5	
6	// ── 常量 ─────────────────────────────────
7	const GRID = 20;
8	const WORLD = { w: 1280, h: 800 };
9	const TYPES = {
10	  chair:  { name: '椅', w: 34,  h: 34 },
11	  desk:   { name: '桌', w: 120, h: 60 },
12	  screen: { name: '屏', w: 88,  h: 56 },
13	  plant:  { name: '植', w: 32,  h: 32 },
14	  lamp:   { name: '灯', w: 36,  h: 36 },
15	  box:    { name: '箱', w: 46,  h: 46 },
16	};
17	const TYPE_ORDER = ['chair', 'desk', 'screen', 'plant', 'lamp', 'box'];
18	const ZONES = [
19	  { id: 'studio',  name: '工作区', x: 40,  y: 40,  w: 560, h: 420, accent: '#5b8def' },
20	  { id: 'meeting', name: '会议区', x: 680, y: 40,  w: 560, h: 420, accent: '#2fae7d' },
21	  { id: 'store',   name: '仓储区', x: 40,  y: 500, w: 560, h: 260, accent: '#d0912f' },
22	  { id: 'gallery', name: '展示区', x: 680, y: 500, w: 560, h: 260, accent: '#a06ae0' },
23	];
