25	// ── 初始数据（随首屏内联就绪，无加载态）──
26	function buildInitial() {
27	  let nextId = 1;
28	  const counters = {};
29	  const mk = (type, x, y) => {
30	    counters[type] = (counters[type] || 0) + 1;
31	    return {
32	      id: nextId++, type, x, y, rot: 0, zone: null,
33	      label: TYPES[type].name + '-' + String(counters[type]).padStart(2, '0'),
34	    };
35	  };
36	  const objects = [
37	    ['desk', 160, 180], ['desk', 300, 300], ['chair', 160, 260], ['chair', 300, 220],
38	    ['screen', 220, 120], ['plant', 540, 120], ['lamp', 360, 180],
39	    ['desk', 900, 250],
40	    ['chair', 820, 170], ['chair', 980, 170], ['chair', 820, 330],
41	    ['chair', 980, 330], ['chair', 900, 140], ['chair', 900, 360],
42	    ['screen', 1160, 120],
43	    ['box', 120, 560], ['box', 180, 560], ['box', 120, 640], ['box', 180, 640],
44	    ['chair', 300, 600], ['lamp', 420, 600],
45	    ['plant', 740, 560], ['plant', 740, 660], ['lamp', 940, 560], ['box', 940, 660],
46	    ['chair', 640, 480], ['box', 640, 300], // 走廊上的两件 → 未落位
47	  ].map((a) => mk(a[0], a[1], a[2]));
48	  return { objects, nextId, counters };
49	}
50	
51	// ── 状态 ─────────────────────────────────
52	const state = {
53	  objects: [], sel: new Set(), snap: true, addType: 'chair',
54	  view: { x: 0, y: 0, w: WORLD.w, h: WORLD.h },
55	};
56	let lastInit = buildInitial();
57	
58	// ── DOM 引用 ─────────────────────────────
59	const $ = (s) => document.querySelector(s);
60	const stage = $('#stage'), viewG = $('#view'), objectsLayer = $('#objectsLayer');
61	const zonesLayer = $('#zonesLayer'), marqueeEl = $('#marquee');
62	const ledgerBody = $('#ledgerBody'), toastsEl = $('#toasts');
63	const stSel = $('#stSel'), stCount = $('#stCount'), stSnap = $('#stSnap'), stZoom = $('#stZoom');
64	const btnSnap = $('#btnSnap'), helpOverlay = $('#helpOverlay');
65	
66	// ── 分区归属：中心点落在哪即归属哪 ────────
67	function zoneOf(o) {
68	  for (const z of ZONES) {
69	    if (o.x >= z.x && o.x <= z.x + z.w && o.y >= z.y && o.y <= z.y + z.h) return z;
70	  }
71	  return null;
72	}
73	const zoneById = (id) => ZONES.find((z) => z.id === id) || null;
74	function refreshMembership() {
75	  for (const o of state.objects) o.zone = zoneOf(o) ? zoneOf(o).id : null;
76	}
77	
78	// ── 渲染 ─────────────────────────────────
79	function zoneLayerSVG() {
80	  let s = '';
81	  for (const z of ZONES) {
82	    s += `<g><rect class="zone-rect" x="${z.x}" y="${z.y}" width="${z.w}" height="${z.h}" `
83	      + `fill="${z.accent}" fill-opacity="0.055" stroke="${z.accent}" stroke-opacity="0.45" stroke-width="1.5"/>`
84	      + `<text class="zone-name" x="${z.x + 18}" y="${z.y + 28}" fill="${z.accent}">${z.name}</text>`
85	      + `<text class="zone-sub" x="${z.x + 18}" y="${z.y + 46}">${z.id}</text></g>`;
86	  }
87	  return s;
88	}
