90	function objSVG(o) {
91	  const t = TYPES[o.type];
92	  const z = zoneById(o.zone);
93	  const acc = z ? z.accent : '#7d8798';
94	  const sel = state.sel.has(o.id);
95	  const rot = o.rot ? ` transform="rotate(${o.rot} ${o.x} ${o.y})"` : '';
96	  const L = o.x - t.w / 2, T = o.y - t.h / 2;
97	  let body = '';
98	  switch (o.type) {
99	    case 'desk':
100	      body = `<rect class="body" x="${L}" y="${T}" width="${t.w}" height="${t.h}" rx="9"/>`
101	        + `<rect x="${L + 10}" y="${T + 8}" width="${t.w - 20}" height="5" rx="2.5" fill="${acc}" fill-opacity="0.5"/>`;
102	      break;
103	    case 'chair':
104	      body = `<circle class="body" cx="${o.x}" cy="${o.y}" r="16"/>`
105	        + `<circle cx="${o.x}" cy="${o.y}" r="6" fill="none" stroke="${acc}" stroke-width="2"/>`;
106	      break;
107	    case 'screen':
108	      body = `<rect class="body" x="${L}" y="${T}" width="${t.w}" height="${t.h}" rx="6"/>`
109	        + `<rect x="${L + 8}" y="${T + 8}" width="${t.w - 16}" height="${t.h - 16}" rx="3" fill="${acc}" fill-opacity="0.35"/>`;
110	      break;
111	    case 'plant':
112	      body = `<circle class="body" cx="${o.x}" cy="${o.y}" r="15"/>`
113	        + `<path d="M${o.x} ${o.y - 12} L${o.x} ${o.y + 12} M${o.x - 10} ${o.y - 6} L${o.x + 10} ${o.y + 6} `
114	        + `M${o.x + 10} ${o.y - 6} L${o.x - 10} ${o.y + 6}" stroke="${acc}" stroke-width="2" fill="none" stroke-linecap="round"/>`;
115	      break;
116	    case 'lamp':
117	      body = `<polygon class="body" points="${o.x},${o.y - 17} ${o.x + 17},${o.y} ${o.x},${o.y + 17} ${o.x - 17},${o.y}"/>`
118	        + `<circle cx="${o.x}" cy="${o.y}" r="3.5" fill="${acc}"/>`;
119	      break;
120	    default: // box
121	      body = `<rect class="body" x="${L}" y="${T}" width="${t.w}" height="${t.h}" rx="5"/>`
122	        + `<line x1="${L}" y1="${o.y}" x2="${L + t.w}" y2="${o.y}" stroke="${acc}" stroke-width="2" stroke-opacity="0.7"/>`;
123	  }
124	  const ring = sel
125	    ? `<rect class="selring" x="${L - 7}" y="${T - 7}" width="${t.w + 14}" height="${t.h + 14}" rx="10"/>`
126	    : '';
127	  const labelY = o.y + t.h / 2 + 14;
128	  return `<g class="obj${sel ? ' sel' : ''}${z ? '' : ' unplaced'}" data-id="${o.id}">`
129	    + `${ring}<g${rot}><g stroke="${acc}" stroke-width="2">${body}</g></g>`
130	    + `<text x="${o.x}" y="${labelY}" fill="${z ? acc : '#7d8798'}">${o.label}</text></g>`;
131	}
