133	function render() {
134	  stage.setAttribute('viewBox', `${state.view.x} ${state.view.y} ${state.view.w} ${state.view.h}`);
135	  let s = '';
136	  for (const o of state.objects) s += objSVG(o);
137	  objectsLayer.innerHTML = s;
138	  renderLedger();
139	  renderStatus();
140	}
141	
142	function renderLedger() {
143	  const groups = ZONES.map((z) => ({ z, items: [] }));
144	  const loose = { z: null, items: [] };
145	  for (const o of state.objects) {
146	    const g = groups.find((g) => g.z.id === o.zone);
147	    (g ? g.items : loose.items).push(o);
148	  }
149	  let html = '';
150	  for (const g of [...groups, loose]) {
151	    const acc = g.z ? g.z.accent : '#7d8798';
152	    const name = g.z ? g.z.name : '未落位';
153	    html += `<div class="zgroup${g.items.length ? '' : ' empty'}">`
154	      + `<div class="zhead"><span class="zdot" style="background:${acc}"></span>`
155	      + `<span class="zname">${name}</span><span class="zcount">${g.items.length} 件</span></div>`
156	      + `<div class="chips">`
157	      + g.items.map((o) => `<button class="chip" data-id="${o.id}" style="--acc:${acc}" title="选中 ${o.label}">${o.label}</button>`).join('')
158	      + `</div></div>`;
159	  }
160	  ledgerBody.innerHTML = html;
161	}
162	
163	function renderStatus() {
164	  const ids = [...state.sel];
165	  if (ids.length) {
166	    const o = state.objects.find((o) => o.id === ids[0]);
167	    if (o) {
168	      const z = zoneById(o.zone);
169	      const extra = ids.length > 1 ? ` 等 ${ids.length} 件` : '';
170	      stSel.textContent = `已选 ${o.label}${extra} · ${z ? z.name : '未落位'} · (${Math.round(o.x)}, ${Math.round(o.y)})${o.rot ? ' · ' + o.rot + '°' : ''}`;
171	    }
172	  } else {
173	    stSel.textContent = '未选中（Tab 循环选择对象）';
174	  }
175	  stCount.textContent = `对象 ${state.objects.length} · 已选 ${state.sel.size}`;
176	  stSnap.textContent = `吸附 ${state.snap ? '开' : '关'}`;
177	  stZoom.textContent = `缩放 ${Math.round(WORLD.w / state.view.w * 100)}%`;
178	  btnSnap.classList.toggle('on', state.snap);
179	}
180	
181	// ── 提示 toast ───────────────────────────
182	function toast(msg) {
183	  const d = document.createElement('div');
184	  d.className = 'toast';
185	  d.innerHTML = msg;
186	  toastsEl.appendChild(d);
187	  requestAnimationFrame(() => d.classList.add('in'));
188	  setTimeout(() => { d.classList.remove('in'); setTimeout(() => d.remove(), 300); }, 1700);
189	  while (toastsEl.children.length > 3) toastsEl.firstChild.remove();
190	}
191	
192	// ── 坐标换算 / 视图 ───────────────────────
193	function toWorld(e) {
194	  const m = viewG.getScreenCTM();
195	  if (!m) return { x: 0, y: 0 };
196	  const p = new DOMPoint(e.clientX, e.clientY).matrixTransform(m.inverse());
197	  return { x: p.x, y: p.y };
198	}
199	function clampView() {
200	  const v = state.view;
201	  v.w = Math.min(2560, Math.max(320, v.w));
202	  v.h = v.w * WORLD.h / WORLD.w;
203	  v.x = Math.min(WORLD.w, Math.max(-WORLD.w, v.x));
204	  v.y = Math.min(WORLD.h, Math.max(-WORLD.h, v.y));
205	}
206	function setView(x, y, w) {
207	  state.view = { x, y, w, h: w * WORLD.h / WORLD.w };
208	  clampView();
209	  render();
210	}
211	function zoomAt(ax, ay, f) {
212	  const v = state.view;
213	  const nw = Math.min(2560, Math.max(320, v.w * f));
214	  const rf = nw / v.w;
215	  setView(ax - (ax - v.x) * rf, ay - (ay - v.y) * rf, nw);
216	}
217	const viewCenter = () => ({ x: state.view.x + state.view.w / 2, y: state.view.y + state.view.h / 2 });
218	
219	// ── 空位查找 ─────────────────────────────
220	function freeSlotInZone(z, avoid) {
221	  const cands = [];
222	  for (let gy = z.y + 60; gy <= z.y + z.h - 40; gy += 70)
223	    for (let gx = z.x + 70; gx <= z.x + z.w - 70; gx += 85)
224	      cands.push({ x: gx, y: gy, d: Math.hypot(gx - (z.x + z.w / 2), gy - (z.y + z.h / 2)) });
225	  cands.sort((a, b) => a.d - b.d);
226	  for (const c of cands) {
227	    if (!avoid.some((o) => Math.hypot(o.x - c.x, o.y - c.y) < 56)) return c;
228	  }
229	  return { x: z.x + z.w / 2, y: z.y + z.h / 2 };
230	}
231	function freeSpotNear(px, py, avoid) {
232	  if (!avoid.some((o) => Math.hypot(o.x - px, o.y - py) < 56)) return { x: px, y: py };
233	  for (let ring = 1; ring <= 8; ring++) {
234	    for (let a = 0; a < 8; a++) {
235	      const x = px + Math.cos(a * Math.PI / 4) * ring * 55;
236	      const y = py + Math.sin(a * Math.PI / 4) * ring * 55;
237	      if (x < 30 || x > WORLD.w - 30 || y < 30 || y > WORLD.h - 30) continue;
238	      if (!avoid.some((o) => Math.hypot(o.x - x, o.y - y) < 56)) return { x, y };
239	    }
240	  }
241	  return { x: px, y: py };
242	}
243	
244	// ── 操作（键盘等价物见 keys.js）──────────
245	const snapv = (v) => (state.snap ? Math.round(v / GRID) * GRID : v);
246	const sortedSel = () => state.objects.filter((o) => state.sel.has(o.id));
247	
248	function labelFor(type) {
249	  let mx = 0;
250	  for (const o of state.objects) {
251	    if (o.type !== type) continue;
252	    const m = /-(\d+)$/.exec(o.label);
253	    if (m) mx = Math.max(mx, +m[1]);
254	  }
255	  return TYPES[type].name + '-' + String(mx + 1).padStart(2, '0');
256	}
257	
258	function moveSelection(dx, dy) {
259	  for (const o of sortedSel()) { o.x += dx; o.y += dy; }
260	  commitMove();
261	}
262	function commitMove() {
263	  const before = new Map(state.objects.map((o) => [o.id, o.zone]));
264	  refreshMembership();
265	  for (const o of sortedSel()) {
266	    if (before.get(o.id) !== o.zone) {
267	      const z = zoneById(o.zone);
268	      toast(`<b>${o.label}</b> 落入 ${z ? z.name : '未落位'}`);
269	    }
270	  }
271	  render();
272	}
273	function moveByKeyboard(dx, dy) {
274	  moveSelection(dx, dy); // 内部已 render；移动不逐次刷 toast，状态栏坐标足够反馈
275	}
276	
277	function sendToZone(zoneId) {
278	  const z = zoneById(zoneId);
279	  if (!z) return;
280	  const sel = sortedSel();
281	  if (!sel.length) { toast('未选中对象——先用 Tab 选择'); return; }
282	  const others = state.objects.filter((o) => !state.sel.has(o.id));
283	  for (const o of sel) {
284	    const slot = freeSlotInZone(z, others);
285	    o.x = Math.round(slot.x); o.y = Math.round(slot.y);
286	    others.push(o);
287	  }
288	  const before = sel.map((o) => [o.id, o.zone]);
289	  refreshMembership();
290	  sel.forEach((o, i) => {
291	    if (before[i][1] !== o.zone) toast(`<b>${o.label}</b> → ${z.name}`);
292	  });
293	  render();
294	}
295	
296	function addNode() {
297	  const label = labelFor(state.addType);
298	  const c0 = viewCenter();
299	  const spot = freeSpotNear(Math.round(c0.x), Math.round(c0.y), state.objects);
300	  const o = { id: nextId(), type: state.addType, x: snapv(spot.x), y: snapv(spot.y), rot: 0, zone: null, label };
301	  state.objects.push(o);
302	  refreshMembership();
303	  state.sel = new Set([o.id]);
304	  const z = zoneById(o.zone);
305	  toast(`新增 <b>${o.label}</b>${z ? ' → ' + z.name : '（未落位）'}`);
306	  render();
307	}
308	let _nextId = 0;
309	function nextId() { return ++_nextId; }
310	
311	function duplicateSelection() {
312	  const sel = sortedSel();
313	  if (!sel.length) return;
314	  const created = [];
315	  for (const o of sel) {
316	    const c = {
317	      id: nextId(), type: o.type, rot: o.rot, zone: null,
318	      x: o.x + GRID, y: o.y + GRID, label: '',
319	    };
320	    c.label = labelFor(c.type);
321	    state.objects.push(c); // 立即入栈：多个副本编号连续递增
322	    created.push(c);
323	  }
324	  refreshMembership();
325	  state.sel = new Set(created.map((o) => o.id));
326	  toast(`已复制 ${created.length} 件（<b>D</b>）`);
327	  render();
328	}
329	
330	function deleteSelection() {
331	  if (!state.sel.size) return;
332	  const n = state.sel.size;
333	  const names = sortedSel().slice(0, 2).map((o) => o.label).join('、');
334	  state.objects = state.objects.filter((o) => !state.sel.has(o.id));
335	  state.sel.clear();
336	  toast(`已删除 ${n} 件（${names}${n > 2 ? '…' : ''}）`);
337	  render();
338	}
339	
340	function cycleType() {
341	  const sel = sortedSel();
342	  if (!sel.length) return;
343	  for (const o of sel) {
344	    o.type = TYPE_ORDER[(TYPE_ORDER.indexOf(o.type) + 1) % TYPE_ORDER.length];
345	    o.label = labelFor(o.type);
346	  }
347	  refreshMembership();
348	  toast(`已切换类型（<b>T</b>）→ ${TYPES[sel[0].type].name}`);
349	  render();
350	}
351	
352	function rotateSelection(dir) {
353	  const sel = sortedSel();
354	  if (!sel.length) return;
355	  for (const o of sel) o.rot = ((o.rot + dir * 15) % 360 + 360) % 360;
356	  renderStatus();
357	  render();
358	}
359	
360	function cycleSelect(back) {
361	  if (!state.objects.length) return;
362	  const list = [...state.objects].sort((a, b) => a.id - b.id);
363	  const cur = list.findIndex((o) => state.sel.has(o.id));
364	  const i = back
365	    ? (cur <= 0 ? list.length - 1 : cur - 1)
366	    : (cur === -1 || cur === list.length - 1 ? 0 : cur + 1);
367	  state.sel = new Set([list[i].id]);
368	  render();
369	}
370	
371	function selectAll() { state.sel = new Set(state.objects.map((o) => o.id)); render(); }
372	function clearSelection() { state.sel.clear(); render(); }
373	function toggleSnap() { state.snap = !state.snap; toast(`网格吸附 ${state.snap ? '开' : '关'}（<b>G</b>）`); render(); }
374	function resetData() {
375	  lastInit = buildInitial();
376	  state.objects = lastInit.objects;
377	  _nextId = lastInit.nextId;
378	  state.sel.clear();
379	  state.snap = true;
380	  setView(0, 0, WORLD.w);
381	  toast('已恢复初始布局');
382	}
383	
384	// ── 指针交互（拖拽 = 键盘的等价操作）──────
385	let drag = null;
386	let spaceDown = false;
387	
388	stage.addEventListener('pointerdown', (e) => {
389	  if (e.button !== 0 && e.button !== 1) return;
390	  try { stage.setPointerCapture(e.pointerId); } catch (_) {}
391	  const w = toWorld(e);
392	  if (spaceDown || e.button === 1) {
393	    drag = { mode: 'pan', sx: e.clientX, sy: e.clientY, v: { ...state.view } };
394	    stage.classList.add('panning');
395	    return;
396	  }
397	  const g = e.target instanceof Element ? e.target.closest('g.obj') : null;
398	  if (g) {
399	    const id = +g.dataset.id;
400	    if (e.shiftKey) {
401	      state.sel.has(id) ? state.sel.delete(id) : state.sel.add(id);
402	    } else if (!state.sel.has(id)) {
403	      state.sel = new Set([id]);
404	    }
405	    drag = { mode: 'move', start: w, moved: false };
406	    render();
407	  } else {
408	    drag = { mode: 'marquee', start: w, base: new Set(state.sel), add: e.shiftKey };
409	    if (!e.shiftKey) { state.sel.clear(); }
410	    render();
411	  }
412	});
413	
414	stage.addEventListener('pointermove', (e) => {
415	  if (!drag) return;
416	  if (drag.mode === 'pan') {
417	    const k = state.view.w / (stage.clientWidth || 1);
418	    state.view.x = drag.v.x - (e.clientX - drag.sx) * k;
419	    state.view.y = drag.v.y - (e.clientY - drag.sy) * k;
420	    clampView();
421	    stage.setAttribute('viewBox', `${state.view.x} ${state.view.y} ${state.view.w} ${state.view.h}`);
422	    renderStatus();
423	    return;
424	  }
425	  const w = toWorld(e);
426	  if (drag.mode === 'move') {
427	    let dx = w.x - drag.start.x, dy = w.y - drag.start.y;
428	    dx = snapv(dx); dy = snapv(dy);
429	    if (dx || dy) {
430	      drag.moved = true;
431	      const sel = sortedSel();
432	      if (!drag.orig) drag.orig = new Map(sel.map((o) => [o.id, { x: o.x, y: o.y }]));
433	      for (const o of sel) {
434	        const p = drag.orig.get(o.id);
435	        o.x = p.x + dx; o.y = p.y + dy;
436	      }
437	      commitMove();
438	    }
439	  } else if (drag.mode === 'marquee') {
440	    drag.cur = w;
441	    drawMarquee(drag);
442	    previewMarquee(drag);
443	  }
444	});
445	
446	stage.addEventListener('pointerup', (e) => {
447	  if (!drag) return;
448	  if (drag.mode === 'move' && drag.moved) { /* commitMove 已在 move 中调用 */ }
449	  if (drag.mode === 'marquee') {
450	    marqueeEl.setAttribute('hidden', '');
451	    if (drag.cur) previewMarquee(drag, true);
452	  }
453	  if (drag.mode === 'pan') stage.classList.remove('panning');
454	  drag = null;
455	});
456	stage.addEventListener('pointercancel', () => { drag = null; stage.classList.remove('panning'); });
457	
458	function drawMarquee(d) {
459	  const x = Math.min(d.start.x, d.cur.x), y = Math.min(d.start.y, d.cur.y);
460	  marqueeEl.removeAttribute('hidden');
461	  marqueeEl.setAttribute('x', x); marqueeEl.setAttribute('y', y);
462	  marqueeEl.setAttribute('width', Math.abs(d.cur.x - d.start.x));
463	  marqueeEl.setAttribute('height', Math.abs(d.cur.y - d.start.y));
464	}
465	function previewMarquee(d, final) {
466	  const x1 = Math.min(d.start.x, d.cur.x), x2 = Math.max(d.start.x, d.cur.x);
467	  const y1 = Math.min(d.start.y, d.cur.y), y2 = Math.max(d.start.y, d.cur.y);
468	  const hit = state.objects.filter((o) => {
469	    const t = TYPES[o.type];
470	    return o.x + t.w / 2 >= x1 && o.x - t.w / 2 <= x2 && o.y + t.h / 2 >= y1 && o.y - t.h / 2 <= y2;
471	  });
472	  const ids = new Set(d.base);
473	  for (const o of hit) {
474	    if (d.add && ids.has(o.id) && !final) ids.delete(o.id);
475	    else ids.add(o.id);
476	  }
477	  if (final) {
478	    state.sel = ids;
479	    render();
480	  } else {
481	    state.sel = ids;
482	    // 只更新对象层与状态栏，避免重建 ledger 造成的开销
483	    let s = '';
484	    for (const o of state.objects) s += objSVG(o);
485	    objectsLayer.innerHTML = s;
486	    renderStatus();
487	  }
488	}
489	
490	stage.addEventListener('wheel', (e) => {
491	  e.preventDefault();
492	  const w = toWorld(e);
493	  zoomAt(w.x, w.y, e.deltaY < 0 ? 1 / 1.12 : 1.12);
494	}, { passive: false });
495	
496	// ── 台账 chip 点击选择 ────────────────────
497	ledgerBody.addEventListener('click', (e) => {
498	  const c = e.target instanceof Element ? e.target.closest('.chip') : null;
499	  if (!c) return;
500	  const id = +c.dataset.id;
501	  if (e.shiftKey) state.sel.has(id) ? state.sel.delete(id) : state.sel.add(id);
502	  else state.sel = new Set([id]);
503	  render();
504	});
505	
506	// ── 工具栏 ───────────────────────────────
507	const typeSeg = $('#typeSeg');
508	function renderTypeSeg() {
509	  typeSeg.innerHTML = TYPE_ORDER.map((t) =>
510	    `<button data-type="${t}" class="${state.addType === t ? 'on' : ''}" title="新增类型：${TYPES[t].name}">${TYPES[t].name}</button>`
511	  ).join('');
512	}
513	typeSeg.addEventListener('click', (e) => {
514	  const b = e.target instanceof Element ? e.target.closest('button[data-type]') : null;
515	  if (!b) return;
516	  state.addType = b.dataset.type;
517	  renderTypeSeg();
518	});
519	$('#btnAdd').addEventListener('click', addNode);
520	btnSnap.addEventListener('click', toggleSnap);
521	$('#btnReset').addEventListener('click', resetData);
522	$('#btnHelp').addEventListener('click', () => { helpOverlay.hidden = !helpOverlay.hidden; });
523	$('#btnCloseHelp').addEventListener('click', () => { helpOverlay.hidden = true; });
524	$('#zIn').addEventListener('click', () => { const c = viewCenter(); zoomAt(c.x, c.y, 1 / 1.25); });
525	$('#zOut').addEventListener('click', () => { const c = viewCenter(); zoomAt(c.x, c.y, 1.25); });
526	$('#zFit').addEventListener('click', () => setView(0, 0, WORLD.w));
527	
528	// ── 启动：首屏即就绪 ─────────────────────
529	state.objects = lastInit.objects;
530	_nextId = lastInit.nextId;
531	refreshMembership();
532	zonesLayer.innerHTML = zoneLayerSVG();
533	renderTypeSeg();
534	render();
535	
536	// 供 keys.js / 自检使用
537	window.__fc = { state, TYPES, TYPE_ORDER, ZONES, GRID, WORLD, zoneById, moveByKeyboard,
538	  sendToZone, addNode, duplicateSelection, deleteSelection, cycleType, rotateSelection,
539	  cycleSelect, selectAll, clearSelection, toggleSnap, setView, zoomAt, resetData,
540	  toggleHelp: () => { helpOverlay.hidden = !helpOverlay.hidden; }, helpOpen: () => !helpOverlay.hidden };
541

